const {test}=require('node:test');const assert=require('node:assert/strict');
const load=()=>Promise.all([import('../zombie-model.mjs'),import('../zombie-prefabs.mjs')]);
test('Two cards, automatic start, no duplicate cards or extra land',async()=>{const [m]=await load();const s=m.fresh();assert.equal(m.CELLS.length,2);assert.deepEqual(m.hand(s),['humans','zombies']);m.place(s,'humans',0,0);assert.equal(s.phase,'placing');assert.throws(()=>m.place(s,'humans',1,0));assert.throws(()=>m.place(s,'zombies',0,0));assert.throws(()=>m.place(s,'blank',1,0));m.place(s,'zombies',1,0);assert.equal(s.phase,'intro');assert.equal(s.actors.length,3);assert.throws(()=>m.place(s,'zombies',1,0));});
test('All advertised prefab outcomes are proven by simulation',async()=>{const [m,{PREFABS}]=await load();const expected={close:{outcome:'won',seconds:11.1,survivors:1,remainingHealth:1,kills:4,rebirths:0},duel:{outcome:'won',seconds:5.7,survivors:1,remainingHealth:3,kills:2,rebirths:0},last:{outcome:'won',seconds:13.8,survivors:1,remainingHealth:2,kills:9,rebirths:2}};for(const p of PREFABS)assert.deepEqual(m.simulate(p.counts),expected[p.id]);});
test('Playback partitions, pause and save round trip preserve forecast',async()=>{const [m,{PREFABS}]=await load();for(const p of PREFABS){const s=m.fresh(p.counts);m.place(s,'humans',0,0);m.place(s,'zombies',1,0);s.paused=true;const before=JSON.stringify(s);m.step(s,.1);assert.equal(JSON.stringify(s),before);s.paused=false;let copy=JSON.parse(JSON.stringify(s));while(['intro','battle'].includes(copy.phase))m.step(copy,.017);assert.equal(copy.phase,m.simulate(p.counts).outcome);assert.equal(Number(copy.time.toFixed(2)),m.simulate(p.counts).seconds);assert.equal(copy.rebirths,m.simulate(p.counts).rebirths);}});
test('Invalid and extreme custom counts remain bounded',async()=>{const [m]=await load();for(const counts of [{archers:0,peasants:0,zombies:1},{archers:1.5,peasants:0,zombies:2},{archers:1,peasants:0,zombies:13}])assert.throws(()=>m.fresh(counts));assert.equal(m.simulate({archers:0,peasants:1,zombies:12}).outcome,'lost');assert.ok(m.simulate({archers:4,peasants:6,zombies:12}).seconds<180);});
test('Every random difficulty entry reproduces its advertised outcome',async()=>{const [m]=await load();const {RANDOM_POOLS}=await import('../zombie-random.mjs');for(const [difficulty,pool]of Object.entries(RANDOM_POOLS)){assert.ok(pool.length>=3);for(const p of pool){const actual=m.simulate(p.counts);assert.deepEqual(actual,p.result);assert.equal(actual.outcome,difficulty==='death'?'lost':'won');if(difficulty==='easy')assert.equal(actual.remainingHealth,(p.counts.archers+p.counts.peasants)*3);if(difficulty==='hard')assert.ok(actual.survivors<p.counts.archers+p.counts.peasants||actual.remainingHealth<=actual.survivors);}}});
